const MAX_RETRIES = 3;

export class JobQueue {
  private readonly concurrency: number;
  private readonly pending: (() => Promise<void>)[] = [];
  private readonly idleWaiters: (() => void)[] = [];
  private active = 0;

  constructor(concurrency: number) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    this.concurrency = concurrency;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        // ponytail: retries immediately, add backoff if jobs hit rate-limited services
        for (let attempt = 0; ; attempt++) {
          try {
            return resolve(await job());
          } catch (err) {
            if (attempt >= MAX_RETRIES) return reject(err);
          }
        }
      });
      this.next();
    });
  }

  /** Resolves once nothing is running or waiting, regardless of whether jobs succeeded. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private isIdle(): boolean {
    return this.active === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      this.active++;
      void this.pending.shift()!().finally(() => {
        this.active--;
        this.next();
      });
    }
    if (this.isIdle()) this.idleWaiters.splice(0).forEach((resolve) => resolve());
  }
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { setTimeout as sleep } from "node:timers/promises";
import { JobQueue } from "./jobQueue.ts";

test("respects the concurrency limit and onIdle waits for everything", async () => {
  const queue = new JobQueue(2);
  let running = 0;
  let peak = 0;
  let done = 0;
  for (let i = 0; i < 6; i++) {
    void queue.add(async () => {
      peak = Math.max(peak, ++running);
      await sleep(10);
      running--;
      done++;
    });
  }
  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
});

test("retries up to three times, then rejects", async () => {
  const queue = new JobQueue(1);

  let flakyCalls = 0;
  const flaky = queue.add(async () => {
    if (++flakyCalls < 4) throw new Error("flaky");
    return "ok";
  });

  let deadCalls = 0;
  const dead = queue.add(async () => {
    deadCalls++;
    throw new Error("dead");
  });

  assert.equal(await flaky, "ok");
  await assert.rejects(dead, /dead/);
  assert.equal(flakyCalls, 4);
  assert.equal(deadCalls, 4);
  await queue.onIdle();
});

test("onIdle resolves immediately on an empty queue; bad concurrency throws", async () => {
  await new JobQueue(1).onIdle();
  assert.throws(() => new JobQueue(0), RangeError);
});

